  Stage_118135_Name = {
    Text = "ঘূর্ণিপাক"
  },
  Stage_118136_Desc = {
    Text = "লাফাও, নিচে লাফিয়ে পড়ো, প্রিয় লম্বা চুলের রাজকন্যা।\nসেই পতনের স্থানে, অবশ্যই একজন নাইটের উষ্ণ ও দৃঢ় আলিঙ্গন অপেক্ষা করছে।"
