  Stage_141269_Name = {
    Text = "পাঁজরের তরুণাস্থি·প্রথম পর্ব"
  },
  Stage_141270_Desc = {
    Text = "「স্বাধীন ইচ্ছা」। সে চোখ নামিয়ে এই মজাদার শব্দটির দিকে তাকাল, এবং কলমের ডগা দিয়ে আলতো করে সেটি কেটে দিল।\nসে আরেকটি লাইন রেখে গেল।\n@2-এর জিনিস @2-কে ফিরিয়ে দাও, @2-এর জিনিস @2-কে ফিরিয়ে দাও।"
