  Stage_145316_Name = {
    Text = "উপঢৌকন·প্রথম পর্ব"
  },
  Stage_145317_Desc = {
    Text = "সব বিপদের মধ্যে, হিংস্র পশু সবচেয়ে কোমল।"
  },
  Stage_145317_Name = {
    Text = "খাঁচাবন্দী পশু·পঞ্চম পর্ব"
  },
  Stage_145318_Desc = {
    Text = "অবশেষে, তুমি পেয়ে গেছ তোমার কাঙ্ক্ষিত সবকিছু। শক্তি, সম্পদ, গৌরব, কখনো না ফুরানো ক্ষমতা।\nরক্ত মুকুট থেকে ঝরে পড়ে, তোমার দুই চোখ রাঙিয়ে দেয়। প্রাণভরে হেসে ওঠো, হে মহান নতুন রাজা। এই ক্ষমতার লোভের রক্তে, প্রহরা করো তোমার অনিবার্য পচনের।"
  },
