  Stage_20828_Name = {
    Text = "নিদ্রিত সার্বভৌম ট্রায়াল"
  },
  Stage_20852_Desc = {
    Text = "「সে এক। সে সর্ব। সে সেই আশা, যে সত্যের দ্বার উন্মুক্ত করে।」\nঅগণিত চাবি একটি বৃত্ত রচনা করে। তারা আকাশ থেকে ঝরে পড়ে, মানবতার জন্য বয়ে আনে এক ভারী আশা।\nআর ভারী কবর।"
  },
  Stage_20852_Name = {
    Text = "মায়াবী অবগাহন·উন্মাদনা"
  },
  Stage_20853_Desc = {
    Text = "এখানে সমাধিস্থ এক বিশ্ববিদ্যালয়, ভাঙাচোরা ও ক্ষতবিক্ষত, সমস্ত শক্তি শুষে নেওয়া হয়েছে\nএকদা, মানবতার দীপ্তি টিকিয়ে রাখার জন্য সে সাহস করে এক ক্ষীণ গ্লিমার উপহার দিয়েছিল\nতার পরিণতি—এখন তোমার চোখের সামনেই।"
  },
