  Stage_38762_Name = {
    Text = "একটি ক্ষণস্থায়ী স্মৃতি: স্মৃতিচারণ·পর্ব I"
  },
  Stage_38763_Desc = {
    Text = "ইসারাউ অদৃশ্য হয়ে গেল, যেন সে কখনো ছিলই না।\nসব রাস্তা আর মানুষ ছিল মায়াস্বপ্ন। সেগুলো জন্ম নিয়েছিল তার স্বপ্ন থেকে, দিন দিন আকার পেয়েছিল, তারপর:\n「ধাম—」\nস্বপ্নের অবসান। সে কখনো চোখ মেলে ইসারাউকে দেখেনি, যেমন সে কখনো চোখ মেলে নিজেকেও দেখেনি।"
  },
