  Stage_49369_Desc = {
    Text = "চারা গাছেরা হলো বেপরোয়া অভিযাত্রী।\nবীজ জানে না পরের এক ইঞ্চি মাটি উর্বর কালো মাটি, নাকি ঠান্ডা, অনুর্বর বালু—তবু তারা নির্ভীক দৃঢ়তায় শিকড় বাড়িয়ে দেয় মাটির গভীরে।"
  },
