  Stage_51062_Name = {
    Text = "নাটকের শীর্ষবিন্দু·পর্ব VI"
  },
  Stage_51063_Desc = {
    Text = "প্রতিটি মুহূর্তে দর্শকের মস্তিষ্কে গোলাবর্ষণ কোরো না; তাদের ভাবার জন্য কিছু ফাঁকা জায়গা রেখে দাও—আদর্শভাবে, তাদের সম্পূর্ণ স্থিরতায় ফেলে দাও। “শুধু যদি ডল ক্লাসে এটা প্রয়োগ করতে পারত,” রক্ষক বিড়বিড় করল, আর সকলে সম্মত হলো।"
  },
  Stage_51063_Name = {
    Text = "নীরব মুহূর্ত·পর্ব VI"
  },
  Stage_51064_Desc = {
