  Stage_53797_Name = {
    Text = "অসমাপ্ত পাণ্ডুলিপি·পর্ব III"
  },
  Stage_53798_Desc = {
    Text = "তার উপকারক অন্য সবার থেকে আলাদা ছিল: সে গড়া ছিল কুয়াশা দিয়ে。\nমানবতার দীপ্তির উপর বহু আগেই আস্থা হারিয়ে ফেলা সেই মেয়ের কাছে, কুয়াশা দিয়ে গড়া মানুষ আর সোনা বা প্রতীকে গড়া মানুষের মধ্যে তেমন কোনো পার্থক্য ছিল না。\nএই ভুল বিচারের মূল্য তাকে একদিন চুকাতেই হবে—কিন্তু সে আরেক অনেক দূরের কাহিনি।"
  },
