  Stage_53803_Name = {
    Text = "লম্বা-পা কাকু·পর্ব I"
  },
  Stage_53804_Desc = {
    Text = "জন্মদিনে সে পেল এক উপহার: সাদা রেশমের পোশাক, নিখুঁত যত্নে সেলাই করা।\nতারপর তাকে জানানো হলো, সে এই উপহারটি গায়ে চড়াবে এবং নিজেও এক উপহার হয়ে উঠবে—তার বাবা-মায়ের নিবেদিত কবিতা, অন্য কারও উদ্দেশে।"
  },
