  Stage_55142_Name = {
    Text = "ভস্মাবশেষ·উন্মাদনা"
  },
  Stage_55142_StageInitStateText = {
    Text = "অন্তিম"
  },
  Stage_55143_Desc = {
    Text = "ছোট্ট ফুলের ঘরটাই তাদের ক্ষুদ্র রাজ্য。\nএই বিনয়ী সাম্রাজ্যে, তাদের কিছুই নেই—আর তারা অন্য কিছু চায়ও না।"
  },
  Stage_55143_Name = {
    Text = "ক্ষুদ্র রাজ্য·পর্ব IV"
  },
  Stage_55144_Desc = {
    Text = "প্রশংসিত কবিতাটি এনে দিল সবকিছু; বন্ধুর প্রশংসায় সে লজ্জায় লাল হলো। তার কবিতা অবশেষে বন্ধুকে কষ্ট থেকে রক্ষা করেছে—সে তাই বিশ্বাস করেছিল。\nযা সে শোনেনি, তা হলো: বিদ্বেষের বীজ ইতিমধ্যেই বপন হয়ে গেছে, অপেক্ষায় আছে গোলাপের লতায় জড়িয়ে পড়ে সেগুলোকে ধ্বংস করার।"
  },
