  Stage_56917_Name = {
    Text = "উজ্জ্বল পতন·পর্ব V"
  },
  Stage_56918_Desc = {
    Text = "সে শব্দের উৎস অনুসরণ করে মঞ্চে উঠে গেল।\nতার পদক্ষেপ ছিল স্থির, তার ভঙ্গি সংযত।\nকেউ জানত না, সে এসেছে স্বপ্নলোকের টানে—আর সেই স্বপ্নের মালিক বহু আগেই হারিয়ে গেছে।"
  },
