  Stage_56976_Name = {
    Text = "উন্মাদ বিপর্যয়·পর্ব VI"
  },
  Stage_56977_Desc = {
    Text = "তুমি এখনো কেন ছেড়ে দিতে অস্বীকার করছ? কেন এখনো এত একগুঁয়ে, আত্মজাগরণহীন রয়ে গেছ?\n...তাদের রক্ষা করার জন্য?\nযদি সেটাই তোমার উত্তর হয়, তবে শেষ পর্যন্ত তুমি তোমার অস্থি, তোমার রক্ত, তোমার চেতনা—তোমার সবকিছুই সমর্পণ করবে।"
  },
