  Stage_58357_Name = {
    Text = "দৃঢ় বিশ্বাস·পর্ব III"
  },
  Stage_58358_Desc = {
    Text = "AF 315 সালের 2 ডিসেম্বর, তাকে অদৃশ্য ও অস্পৃশ্য ঘোষণা করা হয়。\nসে চিৎকার করেছিল, কিন্তু কেউ সাড়া দেয়নি; সে রুটি চুরি করেছিল, তবু ধরা পড়েনি, বন্দিও হয়নি。\nডিজলিউশন নামে এক রোগ সকলে‌কে সংক্রমিত করল, শুধু সে একাই রয়ে গেল ব্যতিক্রম।"
  },
