  Stage_58364_Name = {
    Text = "স্মৃতির বক্ররেখা·উন্মাদনা"
  },
  Stage_58364_StageInitStateText = {
    Text = "আদি উৎস"
  },
  Stage_58365_Desc = {
    Text = "「আমার আর কিছুই নেই,」 বলল একচোখো পথশিশুটি। 「শুধু এই ফুলটুকুই তোমাকে দিতে পারি, মহামহিম রানি।」\nসে সাদা ফ্রেসিয়াটি হাতে নিল, তবু অদ্ভুত এক বিভ্রান্তি তাকে গ্রাস করল। এই দৃশ্য যেন তার স্মৃতির অতল গহ্বরে অসংখ্যবার অভিনীত হয়েছে।\nঅন্তহীন পুনরাবৃত্তি, যেন সেই গোলকধাঁধা, যেখানে মিনোটর বন্দি ছিল।"
  },
  Stage_58365_Name = {
    Text = "ফ্রিসিয়ার পুষ্প·পর্ব I"
