  Stage_58385_Name = {
    Text = "মরীচিকা·উন্মাদনা"
  },
  Stage_58385_StageInitStateText = {
    Text = "অন্তিম"
  },
  Stage_58386_Desc = {
    Text = "সে চোখ বুজে মহাবিশ্বের শূন্যতায় উদ্দেশ্যহীন ভেসে থাকে।\nএক বছর, একশো বছর... অবশেষে একদিন, সে নিজেকেই বলে: 「ঠিক আছে। সত্য আর মিথ্যার সংজ্ঞা আমিই নির্ধারণ করব।」\nরানি এবং তার অমর নগরী—ইসারাউ, এভাবেই ঝুলে থাকে মহাবিশ্বের বিস্তৃত নক্ষত্রমালার মাঝে।\nইসারাউয়ের গল্প সে আমার সঙ্গে ভাগ করে, যাতে তা চিরকাল স্মরণে থাকে।"
  },
