  Stage_58399_Name = {
    Text = "কূপ·পর্ব I"
  },
  Stage_58400_Desc = {
    Text = "সোনালী নগরী—ইসারাউ।\nতার ঐশ্বর্য অক্ষয়, তার কামনা সীমাহীন।\nএকটি স্পঞ্জের মতো, সে সোনার অন্তহীন স্রোত শোষণ করে ফুলে ওঠে।\nএটাই আমার রাজধানী, রানি বললেন। তিনি এ নিয়ে গর্বিত।"
  },
