  Stage_58414_Name = {
    Text = "আয়নার দৃষ্টি·পর্ব II"
  },
  Stage_58415_Desc = {
    Text = "ঐশ্বরিক রিয়েল্মের অবয়ব উদিত হলো তার চোখের সামনে। ঐশ্বরিক রিয়েল্মের ঘণ্টাধ্বনি প্রতিধ্বনি তুলল তার কানে। রাজ্যের ভবিষ্যদ্বাণী সে পূর্ণ করবে, বিরামহীনভাবে।\nএই কথাগুলোই তাকে পথ দেখিয়েছে তার জীবনের বিস্তীর্ণ অন্ধকার ভেদ করে।"
  },
