  Stage_58439_Name = {
    Text = "বিবর্ণ স্মৃতি·পর্ব VI"
  },
  Stage_58440_Desc = {
    Text = "ওটা হয়ে উঠেছে তার আত্মার সবচেয়ে ঘৃণ্য অংশের প্রতীক।\nওটার সঙ্গে সে কষ্ট পেয়েছে, ওটার সঙ্গেই মরেছে, আর এক অর্থে ওটার সঙ্গেই বিলীন হয়ে গেছে।\nএইভাবে তার হৃদয় হয়ে উঠেছে লোহার মতো, আর সে আর কোনো দয়া দেখায় না।"
  },
