  Stage_59502_Desc = {
    Text = "তোমার আদিম হতাশার মুখোমুখি হও। তোমার আদিম ভয়ের মুখোমুখি হও।\nঅদৃশ্য থেকে পাশাপাশি দাঁড়াও, তারপর তাঁকে জয় করো।"
  },
  Stage_59502_Name = {
    Text = "চূড়ান্ত: আদিম ছায়া"
  },
  Stage_59503_Desc = {
    Text = "স্মরণ করাই তোমার শপথ; বিস্মৃতিই তোমার আচার।"
  },
  Stage_59503_Name = {
    Text = "আচার"
  },
  Stage_59503_StageInitStateText = {
    Text = "আদি উৎস"
  },
  Stage_59504_Desc = {
    Text = "স্বপ্নলোকের মন্দিরে দাঁড়িয়ে, ভেঙে পড়া ধ্বংসাবশেষকে ঠেকিয়ে রাখা।\nতোমার পায়ের নিচের ধূলিকণাটিকে প্রহরী হয়ে রক্ষা করা—যে কণায় নিহিত আছে তোমার সমস্ত ভক্তি আর আকুলতা।"
  },
