  Stage_70426_Name = {
    Text = "বিড়ালের দৃষ্টি·পর্ব I"
  },
  Stage_70427_Desc = {
    Text = "কি অপূর্ব রাত—যে রাতের প্রতিটি মুহূর্তে বিড়াল ডুবে থাকতে চায়, আর কখনো ভুলো না!\nজালি-জানালা ভেদ করে নির্মল চাঁদের আলো ঢুকতে দাও, আর পড়তে দাও এই উল্লাসমুখর ভোজের উপর!\nওহ, বিড়ালদের স্তব করো!"
  },
