  Stage_75770_StageInitStateText = {
    Text = "অন্তিম"
  },
  Stage_75771_Desc = {
    Text = "ধূসর সাগরের কোনো শেষ নেই।\nযে সব আত্মার আশ্রয় নেই, তারা সবাই এখানে জড়ো হয়, গড়িয়ে চলা ঢেউয়ের ভাঁজে, উঠানামার মাঝে।\nতারা গা ঘেঁষে বসে, হাসে, আর কাঁদে। তারা তোমার দিকে তাকিয়ে থাকে। তারা অপেক্ষা করে, পরের জনটি তাদের সঙ্গে যোগ দেবে বলে।"
  },
