  Stage_7704_Desc = {
    Text = "জীবন, গোপনীয়তার সঙ্গে জড়িত হোক বা না হোক, ঘুরপাক খায় রোজ স্ক্রিপকে কেন্দ্র করে।\nডিজলিউশনের ধ্বংসস্তূপে, যেখানে সাধারণ মানুষের বেঁচে থাকা অসম্ভব, সেখানে হয়তো লুকিয়ে আছে অপরিমেয় মূল্যের গোপন সম্পদ।"
  },
  Stage_7704_Name = {
    Text = "গোল্ড ভাউচার অনুসন্ধান 2"
  },
  Stage_77050_Desc = {
