  Stage_79587_Name = {
    Text = "অগ্নি-মথ·পর্ব III"
  },
  Stage_79588_Desc = {
    Text = "এই মুহূর্ত থেকে, আমার সঙ্গে নির্ভয়ে কথা বলো—তোমার স্মৃতিচারণ আমার সামনে উন্মুক্ত করে দাও।\nএই মুহূর্ত থেকে, দ্বিধাহীনভাবে আমার আনুগত্য স্বীকার করো—তোমার মন আমার জিম্মায় সমর্পণ করো।\nতোমার স্মৃতি-গহীনের গভীরে যে সত্যিকারের সত্তা বাস করে, আমি তোমাকে সেই রূপেই গড়ে তুলব।"
  },
