  },
  Stage_7999_Name = {Text = "24"},
  Stage_8000_Desc = {
    Text = "হ্যাঁ হ্যাঁ, ঠিকই তো। চোখ হলো মনের কারাগার; আত্মা, দেহের শিকল।"
  },
  Stage_8000_Name = {
    Text = "শারীরবিদ্যার বিষণ্ণতা"
  },
  Stage_8001_Desc = {
    Text = "হ্যাঁ, ঠিক তাই, সোনা। যত খুশি কাঁদো, আর তোমার যন্ত্রণাকে ফ্রেমবন্দি করো এক মহাকাব্যিক ছবির মতো।"
  },
  Stage_8001_Name = {
    Text = "কুমারী ও অশ্রু"
  },
  Stage_8002_Desc = {
    Text = "「হাত」 রাত্রির পর্দা সরিয়ে তোলে, নীরবে এই জগতে আগমন করে।"
  },
  Stage_8002_Name = {
    Text = "মায়াবী অবগাহন I"
