  Stage_8060_Name = {
    Text = "ঝড়ভেদ"
  },
  Stage_8062_Desc = {
    Text = "আমরা পোকামাকড়, অস্থি আর অশ্রুর সমাবেশ।\nআজ রাতে আমরা এক উদ্দেশ্যে এখানে সমবেত—অগণিত রঙধনুতে ভরা যে নদী বয়ে যায়, তা দর্শনের জন্য।"
  },
  Stage_8062_Name = {
    Text = "করোটি শিকারের সমাবেশ"
  },
  Stage_8063_Desc = {
    Text = "「সে এক। সে সর্ব। সে সেই আশা, যে সত্যের দ্বার উন্মুক্ত করে।」\nঅগণিত চাবি একটি বৃত্ত রচনা করে। তারা আকাশ থেকে ঝরে পড়ে, মানবতার জন্য বয়ে আনে এক ভারী আশা।\nআর ভারী কবর।"
  },
