  Stage_8152_Name = {
    Text = "চতুর্দিকে অতর্কিত আক্রমণ"
  },
  Stage_8153_Desc = {
    Text = "এক ক্লিশে সূচনা: একাকী, স্মৃতিহীন এক রক্ষক।\nপার্থক্য শুধু এই যে, এবার {Male=সে,Female=সে} জাগরণ লাভ করে নির্জন সাগরের বুকে।"
