  Stage_90985_Desc = {
    Text = "কাপুরুষরা আমাদের পথের ধারে কাঁপুক।\nসমস্ত গৌরব রোমের, আর সবচেয়ে হিংস্র কপালেই শোভা পাবে সবচেয়ে সুন্দর লরেলমালা।"
