  Stage_90986_Desc = {
    Text = "উল্লাস আর ফুল, মদ আর ভোজ, সোনা আর গোপন সম্পদ—সবই নিয়ে নাও! পেট ভরে হেসে ওঠো, কারণ এ-ই এক যোদ্ধার প্রাপ্য পুরস্কার।"
  },
