  Stage_97619_Name = {
    Text = "দ্বিতীয় দিন পর্ব III"
  },
  Stage_97620_Desc = {
    Text = "ঈশ্বর সকল বস্তু ও ঘটনাকে ডেকে তাদের নিজ নিজ পথে চলতে আদেশ করলেন।\nশিকড় পচা মাটির গভীরে গেঁথে গেল, নখর, দাঁত আর পালক কামড়ে ধরে, হেঁটে ও হেঁচড়ে এগোল।\nশুকনো অস্থির উপর প্রস্ফুটিত হলো ফুল, দুর্বলদের গ্রাস করল প্রবলরা।\nতিনি সকল সত্তাকে জড়িয়ে পড়া ও লড়াই করার অধিকার দান করলেন।"
  },
