  Stage_99729_Name = {
    Text = "বিশৃঙ্খল নিয়তি"
  },
  Stage_99730_Desc = {
    Text = "উড়ো, উড়ো, হে মুক্তির আকাঙ্ক্ষায় কাতর পাখি।\nমৃদু বাতাস তোমায় তুলে নিয়েছে, ঝড় আর বজ্রের ভেতর দিয়ে বহন করে নিয়ে চলেছে; ঐ কালো ডানাই একদিন প্রতিফলিত করবে রক্তিম ভোরের আলো।"
